#include <iostream>
using namespace std;

// generic class
template <typename T>
class Point{
    public:
    T m_x,m_y;
    Point(T x,T y){
        m_x = x;
        m_y = y;
    }
    void show(){
        cout << "inside template class" << endl;
    }
};
// explicit specialization, it will overload the class generated by template class
template <>
class Point<int>{
    public:
    int m_x,m_y,m_z;
    Point(int x,int y){
        m_x = x;
        m_y = y;
    }
    void show(){
        cout << "inside explicit specialized class" << endl;
    }
};


// generic function
template <typename T,typename Compare >
void swapargs(T &a, T &b, Compare cmp){
    T tmp = a;
    a = b;
    b = tmp;
    cout << "generic class " << endl;
    return;
};

template <>
void swapargs(int& a, int &b, int cmp){
    int tmp = a;
    a = b;
    b = tmp;
    cout << "explicit specialized function" << endl;
    return;
};
int main()
{
   
    int x = 5, y = 10;
    Point<int> z(x,y);
    z.show(); // inside explicit specialized class
    swapargs(x,y,0); // explicit specialized function
    cout << x << " " << y << endl;
    double p = 2.5, q = 3.9;
    swapargs(p,q,0); // generic class
    cout << p << " " << q << endl;
    
    

    return 0;
}
